import { openSync, readFileSync, fstatSync, closeSync, constants } from 'node:fs';

/** Local installer capability. Never generated by the public HTTP server or logged.
 * The installer can renew an expired link; a populated store always closes setup.
 */
export function readBootstrap(path: string | undefined, now = Date.now()) {
  if (!path) return undefined;
  let fd: number | undefined;
  try {
    fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
    const st = fstatSync(fd);
    if (!st.isFile() || st.size > 1024 || st.mode & 0o027 || st.uid !== 0) throw new Error('Invalid local setup capability');
    const data = JSON.parse(readFileSync(fd, 'utf8'));
    if (typeof data.token !== 'string' || !/^[A-Za-z0-9_-]{43}$/.test(data.token) ||
        !Number.isSafeInteger(data.expiresAt) || data.expiresAt <= now || data.expiresAt > now + 15 * 60_000)
      return undefined;
    return { token: data.token as string, expiresAt: data.expiresAt as number };
  } catch (e: any) {
    if (e.code === 'ENOENT') return undefined;
    throw e;
  } finally { if (fd !== undefined) closeSync(fd); }
}
